; regs.asm -- chapter 19: the eight registers, and the bytes that write them
; generated by gen19.py
        INCLUDE "msx.inc"
        OUTPUT "regs.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; TEXT_PAGE writes the eight registers. Then R#7, the border, four times, with
; four second bytes; a byte sent to $98 with no address of its own; and two
; first bytes that the VDP forgets.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
r0:
r1:     ld a, LIGHT_GREEN
        out (VDP_CTRL), a
        ld a, $87               ; bit 7: a register; bits 2-0: which
        out (VDP_CTRL), a
r2:     ld a, DARK_BLUE
        out (VDP_CTRL), a
        ld a, $8F               ; bit 7: a register; bits 2-0: which
        out (VDP_CTRL), a
r3:     ld a, BLACK
        out (VDP_CTRL), a
        ld a, $C7               ; bit 7: a register; bits 2-0: which
        out (VDP_CTRL), a
r4:     ld a, DARK_RED
        out (VDP_CTRL), a
        ld a, $FF               ; bit 7: a register; bits 2-0: which
        out (VDP_CTRL), a
r5:     ld a, WHITE
        out (VDP_CTRL), a
        ld a, $87
        out (VDP_CTRL), a       ; the border white again
        ld a, '*'
        out (VDP_DATA), a       ; a byte and no address: where does it go?
        nop
        nop
        nop
r6:     ld a, LIGHT_GREEN       ; a first byte...
        out (VDP_CTRL), a
        in a, (VDP_CTRL)        ; ...the status read...
        ld a, $87
        out (VDP_CTRL), a       ; ...and the second byte
r7:     in a, (VDP_CTRL)        ; the status again: the $87 forgotten too
r8:     ld a, LIGHT_GREEN       ; a first byte...
        out (VDP_CTRL), a
        ld a, ' '
        out (VDP_DATA), a       ; ...a byte to the VRAM...
        nop
        nop
        nop
        ld a, $87
        out (VDP_CTRL), a       ; ...and the second byte
r9:     in a, (VDP_CTRL)        ; forgotten: back in step
r10:
        VDP_REG 1, $C0          ; display on: the page is finished
done:   jr done

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
